  answers: ProfileAnswers
  persona: string
}

export interface Message {
  role: 'user' | 'assistant'
  content: string
}

export interface NoteGroup {
  title: string
  items: string[]
}

export interface PDFAnalysisResult {
  score: number
  explanation: string
  key_points: string[]
}
```

**Step 6: Verify dev server starts**

```bash
npm run dev
```

Expected: `Local: http://localhost:5173/` — kill after verifying.

**Step 7: Commit**

```bash
cd /home/advel/workplace/agora/frontend
git add .
git commit -m "feat: scaffold frontend with Vite, Tailwind v4, React Query, React Router"
```

