## Task 8: Frontend localStorage + API client

**Step 1: Write the failing test**

Create `frontend/src/lib/localStorage.test.ts`:

```typescript
import { describe, it, expect, beforeEach } from 'vitest'
import { getProfile, saveProfile, clearProfile } from './localStorage'
import type { StoredProfile } from '../types'

const mockProfile: StoredProfile = {
  answers: {
    name: 'Maria',
    situation: 'refugee',
    city: 'Munich',
    concern: 'housing',
    language: 'Ukrainian',
  },
  persona: 'Maria, Ukrainian refugee, Munich.',
}

describe('localStorage helpers', () => {
  beforeEach(() => localStorage.clear())

  it('returns null when no profile is stored', () => {
    expect(getProfile()).toBeNull()
  })

  it('saves and retrieves a profile', () => {
    saveProfile(mockProfile)
    expect(getProfile()).toEqual(mockProfile)
  })

  it('clearProfile removes the profile', () => {
    saveProfile(mockProfile)
    clearProfile()
    expect(getProfile()).toBeNull()
  })
})
```

**Step 2: Run test to verify it fails**

```bash
cd /home/advel/workplace/agora/frontend
npm test
```

Expected: FAIL — cannot find module './localStorage'

**Step 3: Write `frontend/src/lib/localStorage.ts`**

```typescript
import type { StoredProfile } from '../types'

const KEY = 'clara_profile'

export function getProfile(): StoredProfile | null {
  const raw = localStorage.getItem(KEY)
  if (!raw) return null
  try {
    return JSON.parse(raw) as StoredProfile
  } catch {
    return null
  }
}

export function saveProfile(profile: StoredProfile): void {
  localStorage.setItem(KEY, JSON.stringify(profile))
}

export function clearProfile(): void {
  localStorage.removeItem(KEY)
}
```

**Step 4: Run test to verify it passes**

```bash
npm test
```

Expected: 3/3 PASS

**Step 5: Write `frontend/src/api/client.ts`**

```typescript
import type { Message, NoteGroup, PDFAnalysisResult, ProfileAnswers } from '../types'

const BASE = '/api'

export async function generatePersona(answers: ProfileAnswers): Promise<string> {
  const res = await fetch(`${BASE}/persona`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(answers),
  })
  if (!res.ok) throw new Error('Failed to generate persona')
  const data = await res.json()
  return data.persona as string
}

export async function sendChatMessage(
  message: string,
  history: Message[],
  persona: string
): Promise<string> {
  const res = await fetch(`${BASE}/chat`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ message, history, persona }),
  })
  if (!res.ok) throw new Error('Failed to send message')
  const data = await res.json()
  return data.reply as string
}

export async function fetchNotes(
  history: Message[],
  persona: string
): Promise<NoteGroup[]> {
  const res = await fetch(`${BASE}/notes`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ history, persona }),
  })
  if (!res.ok) throw new Error('Failed to fetch notes')
  const data = await res.json()
  return data.groups as NoteGroup[]
}

export async function analyzePDF(
  file: File,
  persona: string
): Promise<PDFAnalysisResult> {
  const form = new FormData()
  form.append('file', file)
  form.append('persona', persona)
  const res = await fetch(`${BASE}/pdf`, { method: 'POST', body: form })
  if (!res.ok) throw new Error('Failed to analyse PDF')
  return res.json() as Promise<PDFAnalysisResult>
}
```

**Step 6: Commit**

```bash
cd /home/advel/workplace/agora/frontend
git add .
git commit -m "feat: add localStorage helpers and API client"
```

---

## Notes
- Work directory: `/home/advel/workplace/agora/frontend`
- The Vite scaffold generates some boilerplate files (App.tsx, App.css, assets/). Leave them for now — they'll be replaced in Task 9.
- Don't worry about TypeScript errors from Vite's generated files — those get overwritten later
- If `@tailwindcss/vite` has issues, fall back to: `npm install tailwindcss postcss autoprefixer` + `npx tailwindcss init -p` and update vite.config.ts to not import tailwindcss plugin (use PostCSS instead)

